CREATE TABLE IF NOT EXISTS solar_connector_secrets (owner TEXT NOT NULL, connector_id TEXT NOT NULL, ciphertext TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(owner,connector_id));
CREATE TABLE IF NOT EXISTS solar_connector_sessions (id TEXT PRIMARY KEY, owner TEXT NOT NULL, actor TEXT NOT NULL, project_id TEXT NOT NULL, connector_id TEXT NOT NULL, ciphertext TEXT NOT NULL, expires_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_connector_sessions_expiry ON solar_connector_sessions(expires_at);
CREATE TRIGGER IF NOT EXISTS guard_tracked_cable_stock BEFORE UPDATE ON stock_balances WHEN NEW.quantity < CAST(ROUND(COALESCE((SELECT SUM(json_extract(data,'$.remainingLength')) FROM records WHERE owner=NEW.owner AND kind='cableDrums' AND archived=0 AND json_extract(data,'$.status')='active' AND json_extract(data,'$.productId')=NEW.product_id AND json_extract(data,'$.warehouse')=NEW.warehouse),0)*1000) AS INTEGER) BEGIN SELECT RAISE(ABORT,'tracked_cable_stock_requires_drum_action'); END;
